def util = ctx.rigsignal?.gpu?.utilisation_pct;
if (util != null && (util < 0 || util > 100)) {
  throw new Exception('rigsignal.gpu.utilisation_pct must be 0-100, got: ' + util);
}
def temp = ctx.rigsignal?.gpu?.temperature_c;
if (temp != null && (temp < -10 || temp > 150)) {
  throw new Exception('rigsignal.gpu.temperature_c out of plausible range: ' + temp);
}

if (ctx.rigsignal == null) ctx.rigsignal = [:];
if (ctx.rigsignal.gpu == null) ctx.rigsignal.gpu = [:];
def hotspot = ctx.rigsignal?.gpu?.hotspot_c;
def edge = ctx.rigsignal?.gpu?.temperature_c;
def temp = (hotspot != null) ? hotspot : edge;
ctx.rigsignal.gpu.thermal_throttle_warning = (temp != null && temp > 95.0);
